label:
run: order_items -> {
  group_by: category
  aggregate: total_sales
  order_by: total_sales desc
}

run: order_items -> {
  group_by: brand
  aggregate: margin_rate, total_sales
  order_by: margin_rate desc
}

run: order_items -> {
  where: created_at ? @2025
  group_by: order_month is created_at.month
  aggregate: total_sales
  order_by: total_sales desc
}

run: order_items -> {
  group_by: customers.customer_id, customers.full_name
  aggregate: total_sales
  order_by: total_sales desc
  limit: 5
}

run: order_items -> {
  where: customer_id = 884
  aggregate: total_sales, order_item_count, order_count is count(order_id)
}

run: order_items -> {
  where: created_at ? @2025 and status != 'Cancelled' and status != 'Returned'
  aggregate: net_sales is total_sales
}

run: order_items -> {
  where: created_at ? @2025, status != 'Cancelled' and status != 'Returned'
  aggregate: net_sales is total_sales
}

run: order_items -> {
  where: customers.signup_date = @2025
  aggregate: total_sales
}

run: order_items -> {
  aggregate:
    line_count is count()
    priced_lines is count(products.retail_price)
    sale_lines is count(sale_price)
    negative_discount_lines is count() { where: sale_price > products.retail_price }
}

run: order_items -> {
  aggregate:
    line_count is count()
    null_retail_price is count() { where: products.retail_price = null }
    null_sale_price is count() { where: sale_price = null }
    negative_discount_lines is count() { where: sale_price > products.retail_price }
}

run: order_items -> {
  group_by: region
  aggregate: total_sales
  order_by: total_sales desc
}

run: order_items -> { where: created_at ? @2025-06-01 to @2025-09-01
  aggregate: total_sales
}
